def transform(grid):
    # Infer the undamaged pattern at each variable pixel from repetition across
    # the four tiled copies, using the more frequent value in the row.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if c % 3 != 2 and c < 12:
                vals = [grid[r][k] for k in range(c % 3, 12, 3)]
                out[r][c] = max(set(vals), key=vals.count)
    return out
