def transform(grid):
    out = [row[:] for row in grid]
    starts = (0, 3, 6, 9, 12)
    for r in range(len(grid)):
        for k in (0, 1):
            vals = [grid[r][s+k] for s in starts if s+k < len(grid[r])]
            # Each corresponding pixel across the repeated panels is repaired
            # by majority; ties retain the original value at that position.
            counts = {v: vals.count(v) for v in set(vals)}
            winner = max(counts, key=counts.get)
            for s in starts:
                if s+k < len(out[r]):
                    out[r][s+k] = winner
    return out
